async def stop(self) -> None:
    """Shut down: no open connections and no pending tasks afterwards."""
    # Stop accepting new connections, but do NOT wait_closed() yet: on
    # Python >=3.12 it blocks until every client handler exits, which
    # cannot happen while peers are still attached.
    server = self._server
    self._server = None
    if server is not None:
        server.close()
    # Cut every subscriber (cancels writer loops, unblocks their handlers).
    for sub in list(self._subs):
        self._drop(sub, "broker shutdown")
    pending = {t for t in self._tasks if not t.done()}
    if pending:
        _, still_pending = await asyncio.wait(pending, timeout=1.0)
        for t in still_pending:  # force-cancel anything wedged (e.g. silent peers)
            t.cancel()
        if still_pending:
            await asyncio.gather(*still_pending, return_exceptions=True)
    if server is not None:
        await server.wait_closed()
    self._topic_subs.clear()
    log.info("broker stopped")

